  "Équilibrée": "Balanced",
  "Exemples : versement à la banque des espèces prélevées au tiroir (débit 521, crédit 585), frais bancaires (débit 631, crédit 521), loyer payé (débit 6222, crédit 521), à-nouveaux de début d'exercice (journal AN).": "Examples: bank deposit of cash taken from the drawer (debit 521, credit 585), bank charges (debit 631, credit 521), rent paid (debit 6222, credit 521), opening balances at the start of the year (AN journal).",
