  "à ce jour": "to date",
  "Chiffre d'affaires": "Turnover",
  "HT de marchandises sont entrées en stock sans facture fournisseur. Le stock les compte mais pas les achats : le résultat est surévalué d'autant tant que ces factures ne sont pas saisies (Fournisseur › Factures et avoirs fournisseurs). Pour le stock de départ, faites passer une écriture d'à-nouveaux par votre comptable.": "excl. VAT of goods have entered stock without a supplier invoice. The stock counts them but purchases do not: the result is overstated by that amount until these invoices are entered (Supplier › Supplier invoices and credit notes). For the opening stock, have your accountant post an opening balance entry.",
  "Comptes non repris dans les états, à vérifier :": "Accounts not included in the statements, to check:",
  "Amort. dépréc.": "Depr. impair.",
  "La trésorerie du bilan (": "The balance sheet cash (",
  ") diffère de la ligne ZH de": ") differs from line ZH of",
  ": une écriture sort du schéma habituel (immobilisation ou capital passé sans contrepartie de trésorerie, par exemple). Vérifiez-la avant de remettre le tableau.": ": an entry falls outside the usual pattern (fixed asset or capital posted without a cash counterpart, for example). Check it before handing in the statement.",
  "Tableau des flux de trésorerie": "Cash flow statement",
  "Notes calculées à partir des écritures de l'exercice. Les notes déclaratives (1, 2, 13B, 27B et 35) viennent de l'onglet Notes déclaratives.": "Notes calculated from the year's entries. The declarative notes (1, 2, 13B, 27B and 35) come from the Declarative notes tab.",
  "· déclarée": "· declared",
  "· néant": "· nil",
  "Méthode indirecte du SYSCOHADA : on part du résultat net, on retire ce qui ne se paie pas (amortissements, provisions, cessions), puis on suit les variations du bilan. Les à-nouveaux de reprise comptent comme trésorerie de départ, pas comme des flux. La ligne ZH doit égaler la trésorerie du bilan.": "SYSCOHADA indirect method: start from the net result, remove what is not paid (depreciation, provisions, disposals), then follow the balance sheet changes. Takeover opening balances count as opening cash, not as flows. Line ZH must equal the balance sheet cash.",
  "Le stock de marchandises est valorisé au coût moyen pondéré d'après les mouvements de stock (": "The stock of goods is valued at weighted average cost from stock movements (",
  "au début de l'exercice,": "at the start of the year,",
  "à la date choisie) : l'écart passe en variation de stock (compte 6031), comme l'écriture d'inventaire. Les résultats des exercices précédents apparaissent en report à nouveau tant qu'ils ne sont pas affectés par une écriture.": "at the chosen date): the difference goes to change in stock (account 6031), like the inventory entry. Results of previous years appear as retained earnings as long as they are not allocated by an entry.",
  "Magasin au régime simplifié : les nouvelles pièces sont sans TVA. Ce tableau ne reprend que les pièces faites quand la TVA était active.": "Store under the simplified regime: new documents are without VAT. This table only includes documents made while VAT was active.",
  "Imprimer la déclaration": "Print the return",
  "Chiffre d'affaires HT": "Turnover excl. VAT",
  "dont exonéré": "of which exempt",
  "+ crédit reporté": "+ credit carried forward",
  "dépenses": "expenses",
