  "Ventes par taux": "Sales by rate",
  "Arrondis de TVA ticket par ticket": "VAT rounding receipt by receipt",
  "Aucune vente ce mois-ci": "No sales this month",
  "Ce récapitulatif sert à remplir la déclaration mensuelle sur le portail de la DGI. La TVA collectée est celle des tickets (arrondie ticket par ticket), la TVA déductible celle des factures et avoirs fournisseurs et des dépenses datés du mois.": "This summary is used to fill in the monthly return on the DGI portal. The VAT collected is that of the receipts (rounded receipt by receipt), the deductible VAT that of supplier invoices and credit notes and expenses dated in the month.",
  "L'acompte d'impôt sur le résultat (minimum de perception) est calculé sur le chiffre d'affaires HT du mois, au taux du régime choisi dans Fiscal › Impôt sur le résultat. Les précomptes et le droit d'accises restent à ajouter par votre comptable.": "The income tax instalment (minimum tax) is calculated on the month's turnover excl. VAT, at the rate of the regime chosen in Tax › Income tax. Withholdings and excise duty are still to be added by your accountant.",
