  "Minimum de perception (%)": "Minimum tax (%)",
  "Taux du Code général des impôts par défaut, hors centimes additionnels communaux (10 % de l'impôt, ajoutés au calcul). L'IRPP des entreprises individuelles suit le barème 10 / 15 / 25 / 35 %. Faites valider ces taux par votre comptable.": "Default rates from the General Tax Code, excluding communal additional cents (10 % of the tax, added to the calculation). IRPP for sole proprietorships follows the 10 / 15 / 25 / 35 % scale. Have these rates confirmed by your accountant.",
  "Acomptes mensuels (minimum de perception)": "Monthly instalments (minimum tax)",
  "Voir le grand livre": "See the general ledger",
  "Total trésorerie": "Total cash",
  "La caisse (571) regroupe les espèces du magasin, tiroirs et coffre : ventes en espèces nettes de la monnaie rendue, règlements clients en espèces et écarts de clôture. Les prélèvements faits pendant la journée passent au compte 585 jusqu'à leur dépôt à la banque, que vous saisissez dans Journaux (débit 521, crédit 585). MTN MoMo et Orange Money reçoivent les paiements mobiles des ventes et des clients, moins les paiements aux fournisseurs.": "The cash account (571) groups the store's cash, drawers and safe: cash sales net of change given, customer payments in cash and closing differences. Cash taken during the day goes to account 585 until it is deposited at the bank, which you enter in Journals (debit 521, credit 585). MTN MoMo and Orange Money receive the mobile payments from sales and customers, less payments to suppliers.",
