  "Importez le relevé de la banque ou de MoMo / Orange Money (fichier CSV), puis pointez : chaque opération du relevé avec son écriture. Ce qui reste d'un côté explique l'écart entre les deux soldes : chèques pas encore encaissés, frais pas encore comptabilisés… Les à-nouveaux sont considérés comme déjà rapprochés.": "Import the bank or MoMo / Orange Money statement (CSV file), then match: each statement operation with its entry. Whatever remains on one side explains the difference between the two balances: cheques not yet cashed, fees not yet posted… Opening balances are considered already reconciled.",
