  "Un exercice dure en général 12 mois (du 1er janvier au 31 décembre). À sa clôture, les soldes passent en à-nouveaux et plus rien ne se saisit dedans.": "A financial year usually lasts 12 months (from 1 January to 31 December). At closing, balances become opening balances and nothing more can be entered in it.",
