  "ONIX 360 se met à jour tout seul : il cherche une nouvelle version au démarrage puis toutes les 4 heures, la télécharge sans gêner la caisse et l'installe à la prochaine fermeture du logiciel. Les nouvelles versions se déposent dans ONIX 360 Serveur, onglet « Mises à jour ».": "ONIX 360 updates itself: it looks for a new version at start-up and then every 4 hours, downloads it without disturbing the till and installs it the next time the software closes. New versions are dropped into ONIX 360 Server, « Updates » tab.",
