  "Toutes les actions sur cette fiche": "All actions on this record",
  "La base de ce PC est copiée automatiquement (chaque jour, ou plus souvent selon la fréquence choisie), pendant que la caisse travaille. Gardez aussi une copie hors du PC (clé USB, dossier OneDrive ou Google Drive) : en cas de vol ou de panne du disque, c'est elle qui sauve les ventes, le stock et la comptabilité.": "This PC's database is copied automatically (every day, or more often according to the chosen frequency) while the till is working. Also keep a copy off the PC (USB key, OneDrive or Google Drive folder): in case of theft or disk failure, it is what saves sales, stock and accounts.",
