  "Après chaque sauvegarde, une copie chiffrée de la base part sur le serveur central. En cas de vol, d'incendie ou de panne du PC, vous la récupérez sur un autre PC relié au serveur.": "After each backup, an encrypted copy of the database goes to the central server. In case of theft, fire or PC failure, you get it back on another PC linked to the server.",
  "Ce PC n'est pas relié au serveur central (Administration › Serveur central) : la sauvegarde en ligne n'est pas disponible.": "This PC is not linked to the central server (Administration › Central server): online backup is not available.",
