  "Notez cette phrase et gardez-la en lieu sûr, hors du magasin. Sans elle, les sauvegardes en ligne ne peuvent pas être lues : l'éditeur ne la connaît pas et ne peut pas la retrouver.": "Write this phrase down and keep it somewhere safe, outside the store. Without it, online backups cannot be read: the publisher does not know it and cannot recover it.",
