  ", dernière vente le": ", last sale on",
  "Tout ce qui a été fait sur ce PC après cette date (ventes, réceptions, écritures) disparaît de ce PC. La base actuelle est d'abord copiée dans le dossier des sauvegardes (« Avant restauration ») pour pouvoir revenir en arrière. L'application redémarre ensuite.": "Everything done on this PC after that date (sales, receipts, entries) disappears from this PC. The current database is first copied into the backup folder (« Before restore ») so you can go back. The application then restarts.",
