  "Cochez ce que chaque rôle peut ouvrir et faire. L'administrateur a toujours tous les droits. Un changement vaut pour tous les utilisateurs du rôle, à leur prochaine connexion. Pour une seule personne, utilisez « Privilèges par utilisateur ».": "Tick what each role can open and do. The administrator always has all rights. A change applies to all users with the role, at their next sign-in. For a single person, use « Privileges per user ».",
