  "Pour chaque nouvel article sans code fabricant, à l'enregistrement : l'unité, chaque carton et pack.": "For each new item without a manufacturer code, when saved: the unit, each carton and pack.",
  "Format des codes internes": "Internal code format",
  "EAN-8 : court, tient sur les petites étiquettes. EAN-13 : même longueur que les codes fabricants.": "EAN-8: short, fits on small labels. EAN-13: same length as manufacturer codes.",
