  "rien à signaler": "nothing to report",
  "Les gestes qui font perdre de l'argent quand ils sont abusés, caissier par caissier.": "Actions that lose money when abused, cashier by cashier.",
  "Chaque caissier est comparé à la moyenne de l'équipe, rapportée au nombre de tickets : les cases en rouge sont nettement au-dessus. Les ouvertures de tiroir, les prix modifiés et les factures supprimées sont ceux enregistrés sur ce PC. Une note élevée n'est pas une preuve : cliquez un caissier pour vérifier chaque geste.": "Each cashier is compared with the team average, relative to the number of receipts: red boxes are clearly above. Drawer openings, changed prices and deleted invoices are those recorded on this PC. A high score is not proof: click a cashier to check each action.",
  "Aucune vente ni aucun geste à contrôler sur cette période.": "No sales or actions to check over this period.",
  "Nettement au-dessus de la moyenne de l’équipe": "Clearly above the team average",
