  "sur 100 (": "out of 100 (",
  "Au-dessus de la moyenne :": "Above average:",
  "Aucun geste à vérifier sur cette période.": "No actions to check over this period.",
  "Quand la banque renvoie un chèque impayé, le montant du chèque et les frais prélevés retournent au compte du client et apparaissent sur son relevé. L'écriture comptable reprend la banque (ou le compte 513 « Chèques à encaisser » si le chèque n'était pas encore remis en banque).": "When the bank returns an unpaid cheque, the cheque amount and the fees charged go back to the customer's account and appear on their statement. The accounting entry reverses the bank (or account 513 « Cheques to cash » if the cheque had not yet been deposited).",
