  "Pertes déclarées (casse, vol, périmés, consommation interne) et écarts d'inventaire en moins, comptés au prix de revient, rayon par rayon, comparés au chiffre d'affaires du rayon sur la même période.": "Declared losses (breakage, theft, expired, own use) and negative stocktake differences, counted at cost price, department by department, compared with the department's turnover over the same period.",
