  "% des ventes": "% of sales",
  "L'inventaire de la semaine est ouvert dans l'onglet Inventaires": "This week's stocktake is open in the Stocktakes tab",
  "Chaque semaine, une courte liste de produits à compter, choisis pour leur valeur en stock, leurs écarts passés et le temps depuis leur dernier comptage. Le magasin ne ferme jamais pour un grand inventaire : tout le stock finit par être compté, les produits chers et sensibles plus souvent.": "Each week, a short list of products to count, chosen for their stock value, their past differences and the time since they were last counted. The store never closes for a big stocktake: all the stock ends up being counted, expensive and sensitive products more often.",
