  "compressée :": "compressed:",
  "). Joignez ce fichier à un e-mail ou un message WhatsApp.": "). Attach this file to an e-mail or a WhatsApp message.",
  "Travaillez ici comme dans la boutique : articles, prix, clients, paramètres, comptabilité… La caisse ne vend pas. Quand vous avez fini, remettez la fiche sur la clé USB et rapportez-la : dans la boutique, Administration › Fiches boutique › Rapporter une fiche ajoute vos modifications sans rien effacer de ce qu'elle a vendu entre-temps.": "Work here as in the shop: items, prices, customers, settings, accounts… The till does not sell. When you have finished, put the file back on the USB key and bring it back: in the shop, Administration › Shop files › Bring back a file adds your changes without erasing anything it sold in the meantime.",
  "Compresser pour l'envoyer…": "Compress to send it…",
  "Ouvrir une autre boutique": "Open another shop",
  "Remettre la copie sur la clé USB": "Put the copy back on the USB key",
  "Une fiche est une copie de la boutique dans un seul fichier, à emporter sur une clé USB. La boutique n'est jamais arrêtée : la fiche se prend pendant que la caisse vend, et au retour seules les modifications faites dans la fiche sont ajoutées.": "A file is a copy of the shop in a single file, to take away on a USB key. The shop is never stopped: the file is taken while the till is selling, and on return only the changes made in the file are added.",
  "Le technicien l'emporte, l'ouvre sur son PC (Ouvrir une boutique › Ouvrir une fiche), y travaille puis la rapporte. La caisse ne vend pas dans la fiche.": "The technician takes it away, opens it on their PC (Open a shop › Open a file), works in it then brings it back. The till does not sell in the file.",
  "Emporter une fiche d'intervention…": "Take away an intervention file…",
  "Fiche compressée à joindre à un e-mail ou un message WhatsApp": "Compressed file to attach to an e-mail or a WhatsApp message",
  "Envoyer…": "Send…",
  "Copie pour le comptable": "Copy for the accountant",
  "Le comptable fait ses états chez lui. À sa prochaine visite, il prend simplement une nouvelle copie.": "The accountant prepares their statements at home. On their next visit, they simply take a new copy.",
  "Copie pour le comptable…": "Copy for the accountant…",
  "Copie compressée à joindre à un e-mail ou un message WhatsApp": "Compressed copy to attach to an e-mail or a WhatsApp message",
  "Rapporter une fiche": "Bring back a file",
  "Ajoute à la boutique ce qui a été fait dans la fiche. Si un même élément a changé des deux côtés, la modification la plus récente est gardée.": "Adds to the shop what was done in the file. If the same item changed on both sides, the most recent change is kept.",
  "Rapporter une fiche…": "Bring back a file…",
  "Boutique paramétrée au bureau (magasin, utilisateurs, articles), sans vente d'essai. Sur le PC du client, au premier démarrage : « Installer une boutique préparée ».": "Shop set up at the office (store, users, items), without test sales. On the customer's PC, at first start-up: « Install a prepared shop ».",
