  "Vérifie le fichier de la boutique et recalcule le stock et les lots à partir des mouvements, sans toucher la base à la main. La caisse continue de vendre pendant la vérification et la réparation.": "Checks the shop file and recalculates stock and batches from the movements, without touching the database by hand. The till keeps selling during the check and the repair.",
