  "Ces lignes remplacent le réglage de base pour ce client. Sans ligne, le réglage de base s’applique (si le client est coché « à ristourne »).": "These lines replace the base setting for this customer. Without lines, the base setting applies (if the customer is ticked « with rebate »).",
  "Choisissez un client pour lui donner un réglage propre.": "Choose a customer to give them their own setting.",
  "Aucune écriture de ristourne sur la période.": "No rebate entries over the period.",
  "Imprimer le bon": "Print the voucher",
  "Remontée du poste distant": "Remote station upload",
  "Mise à jour de la boutique": "Shop update",
  "Ce PC est un poste distant : il vend sans réseau. Chaque soir, faites la remontée et portez le fichier à la boutique (ou envoyez-le par e-mail ou WhatsApp). Quand la boutique vous renvoie une mise à jour (prix, articles, utilisateurs), intégrez-la ici.": "This PC is a remote station: it sells without a network. Every evening, do the upload and take the file to the shop (or send it by e-mail or WhatsApp). When the shop sends you back an update (prices, items, users), import it here.",
  "depuis la dernière remontée.": "since the last upload.",
