  "CA comparé": "Compared turnover",
  "− coût d'achat moyen (CMUP) des articles au moment de la vente. Les retours sont déduits au coût de la vente d'origine.": "− the items' weighted average purchase cost at the time of sale. Returns are deducted at the cost of the original sale.",
