  "PC relié :": "Linked PC:",
  "Rejoindre un magasin": "Join a store",
  "Sur le PC principal, dans Administration › Caisses, créez une caisse et notez son code d'activation. Ce PC récupère ensuite le catalogue, les utilisateurs et le stock du magasin depuis le serveur central.": "On the main PC, in Administration › Registers, create a register and note its activation code. This PC then gets the store's catalogue, users and stock from the central server.",
  "Adresse du serveur central": "Central server address",
  "Code d'activation de la caisse": "Register activation code",
  "Récupération des données…": "Retrieving data…",
  "Ce fichier n'est pas une installation préparée : au bureau, faites Administration › Fiches boutique › Préparer l'installation": "This file is not a prepared installation: at the office, use Administration › Shop files › Prepare the installation",
  "Installer sur ce PC la boutique «": "Install on this PC the shop «",
  "Installation… ONIX 360 redémarre": "Installing… ONIX 360 is restarting",
  "Les deux codes ne correspondent pas": "The two codes do not match",
  "Bienvenue dans ONIX 360": "Welcome to ONIX 360",
  "Première installation : renseignez votre magasin et le compte administrateur. Vous pourrez ajouter d'autres magasins et caisses ensuite.": "First installation: enter your store and the administrator account. You can add other stores and registers later.",
  "Boutique préparée au bureau ?": "Shop prepared at the office?",
  "Installer une boutique préparée…": "Install a prepared shop…",
  "· Fiche apportée par le technicien ou le comptable ?": "· File brought by the technician or the accountant?",
  "2 à 6 caractères, ex. DLA1": "2 to 6 characters, e.g. DLA1",
  "Les prix sont TTC : la TVA (19,25 %) est calculée et imprimée sur les tickets et les factures.": "Prices include VAT: VAT (19.25 %) is calculated and printed on receipts and invoices.",
  "Régime simplifié : aucune TVA sur les ventes, les achats ni les dépenses. Les tickets portent « TVA non applicable ». Un administrateur pourra l’activer plus tard.": "Simplified regime: no VAT on sales, purchases or expenses. Receipts show « VAT not applicable ». An administrator can enable it later.",
  "Métier": "Business type",
  "Rayons, familles et réglages de départ, modifiables ensuite": "Departments, families and starting settings, editable later",
  "Aucun : je crée mes rayons moi-même": "None: I create my departments myself",
  "Modèle sur clé…": "Template on a key…",
  "4 à 8 chiffres": "4 to 8 digits",
  "Confirmer le code": "Confirm the code",
  "Rejoindre un magasin existant": "Join an existing store",
  "Créer le magasin": "Create the store",
  "Appliquer le modèle «": "Apply the template «",
  "» à cette boutique ? Les rayons et familles qui manquent sont ajoutés, les réglages et les droits du modèle remplacent les vôtres. Rien n'est supprimé.": "» to this shop? Missing departments and families are added, the template's settings and rights replace yours. Nothing is deleted.",
  "Modèle appliqué :": "Template applied:",
  "ajoutés,": "added,",
  "articles créés et": "items created and",
  "mis à jour": "updated",
  "Un modèle prépare une boutique pour son métier : rayons et familles, marge par défaut, alerte de péremption, droits des rôles et, au choix, un catalogue d'articles. On le choisit à la création de la boutique, ou on l'applique ici. Les modèles enregistrés se copient sur une clé pour les installations chez d'autres clients.": "A template prepares a shop for its trade: departments and families, default margin, expiry alert, role rights and, optionally, an item catalogue. It is chosen when the shop is created, or applied here. Saved templates can be copied to a key for installations at other customers.",
  "Enregistrer cette boutique comme modèle…": "Save this shop as a template…",
  "Appliquer un modèle sur clé…": "Apply a template from a key…",
  "Ouvrir le dossier des modèles": "Open the templates folder",
  "(enregistré sur ce PC)": "(saved on this PC)",
