  "Constater les salaires de": "Record the salaries of",
  "Constater un salaire le passe en charge (661) et au sous-compte du collaborateur. Les avances retenues soldent son compte d’avances. Le net se paie ici (bureau) ou à la caisse avec « Décaisser ».": "Recording a salary posts it as a charge (661) and to the staff member's sub-account. Deducted advances clear their advances account. The net is paid here (office) or at the till with « Pay out ».",
  "Les retenues CNPS, IRPP, CAC, CFC, RAV et TDL sont calculées sur le brut des collaborateurs déclarés, avec la part patronale.": "CNPS, IRPP, CAC, CFC, RAV and TDL deductions are calculated on the gross pay of declared staff, with the employer's share.",
