  "Réception enregistrée · imprimer les étiquettes ?": "Receipt recorded · print the labels?",
  "Réception libre, sans bon de commande (lot et date limite). Pour réceptionner une commande : Achats › Bons de commande. Pour saisir la facture en même temps : Achats › Saisir une facture directe.": "Free receipt, without a purchase order (batch and expiry date). To receive an order: Purchases › Purchase orders. To enter the invoice at the same time: Purchases › Enter a direct invoice.",
