  "Coût unit.": "Unit cost",
  "Aucun retour. Un retour fait sortir du stock la marchandise rendue au fournisseur (casse, périmés, erreur de livraison) en attendant son avoir.": "No returns. A return takes out of stock the goods given back to the supplier (breakage, expired, delivery error) while waiting for their credit note.",
  "Dépôt d'où sort la marchandise": "Warehouse the goods leave from",
  "Casse, périmés, erreur de livraison…": "Breakage, expired, delivery error…",
  "Article à rendre (code, nom ou code-barres)": "Item to return (code, name or barcode)",
