  "Quantité rendue": "Quantity returned",
  "La marchandise sort du stock dès l'enregistrement. L'avoir du fournisseur se saisit ensuite depuis le bon.": "The goods leave stock as soon as it is saved. The supplier's credit note is then entered from the note.",
  "Avoir enregistré : il vient en déduction de ce que vous devez au fournisseur": "Credit note recorded: it is deducted from what you owe the supplier",
