  "Enregistrer l'avoir": "Save the credit note",
  "Rechercher un fournisseur": "Search for a supplier",
  "Aucun fournisseur. Créez vos fournisseurs habituels (SABC, Guinness, Nestlé, grossistes…) pour passer vos commandes.": "No suppliers. Create your usual suppliers (SABC, Guinness, Nestlé, wholesalers…) to place your orders.",
