  "Bonus : quantité achetée": "Bonus: quantity bought",
  "Bonus : quantité payée": "Bonus: quantity paid",
  "Les unités gratuites entrent en stock à la réception, sans être payées": "Free units enter stock at receipt, without being paid for",
  "Fournisseur principal de cet article": "Main supplier of this item",
  "Factures et avoirs": "Invoices and credit notes",
  "Réservé au gérant et au comptable.": "Reserved for the manager and the accountant.",
  "Dernières commandes": "Latest orders",
  "Aucune unité gratuite reçue sur la période.": "No free units received over the period.",
  "Unités gratuites": "Free units",
  "Valeur (prix d’achat HT)": "Value (purchase price excl. VAT)",
  "Total des bonus reçus": "Total bonuses received",
  "Une ligne par client : nom, téléphone, plafond, délai de paiement (jours), tarif (détail, gros, super gros) et ce qu’il doit aujourd’hui. Un avoir s’écrit en négatif. Le n° et la date de la facture d’origine, et son échéance, gardent la balance âgée juste. Un client déjà saisi (même nom ou même téléphone) est complété, pas recréé.": "One line per customer: name, phone, limit, payment terms (days), price list (retail, wholesale, bulk) and what they owe today. A credit note is written as a negative. The number and date of the original invoice, and its due date, keep the aged balance right. A customer already entered (same name or same phone) is completed, not created again.",
  "Une ligne par fournisseur : nom, téléphone, NIU, délai de paiement et ce que vous lui devez aujourd’hui, avec le n° de sa facture et l’échéance. La dette reprise se paie ensuite comme une facture d’achat, mais ce n’est pas un achat : ni charge, ni TVA déductible.": "One line per supplier: name, phone, NIU, payment terms and what you owe them today, with their invoice number and due date. The debt taken over is then paid like a purchase invoice, but it is not a purchase: no charge, no deductible VAT.",
  "Une ligne par article : code-barres (ou code interne, ou désignation exacte), quantité et coût de revient unitaire. Le code-barres d’un carton compte en cartons, au prix du carton. Lot et date de péremption pour les articles périssables. Importez d’abord le catalogue (Produit › Importer).": "One line per item: barcode (or internal code, or exact description), quantity and unit cost price. A carton's barcode counts in cartons, at the carton price. Batch and expiry date for perishable items. First import the catalogue (Product › Import).",
  "Reprise terminée :": "Takeover finished:",
  "Rien n’a été importé : corrigez les lignes en erreur, puis recommencez avec le fichier entier.": "Nothing was imported: correct the lines with errors, then start again with the whole file.",
  "? Les écritures d’à-nouveaux seront passées contre le compte d’attente 4711.": "? The opening entries will be posted against suspense account 4711.",
  "Pour un magasin qui tenait ses comptes dans un autre logiciel, dans Excel ou dans un cahier : reprenez ses clients et ce qu’ils doivent, ses fournisseurs et ce que vous leur devez, et son stock de départ. Chaque fichier se vérifie d’abord : rien n’est enregistré tant que vous n’avez pas cliqué « Importer ». S’il reste une ligne en erreur, rien n’est importé.": "For a store that kept its accounts in other software, in Excel or in a notebook: take over its customers and what they owe, its suppliers and what you owe them, and its starting stock. Each file is checked first: nothing is saved until you click « Import ». If a line still has an error, nothing is imported.",
