  "Remise en %": "Discount in %",
  "N achetés, M payés (12/10)": "N bought, M paid (12/10)",
  "Plusieurs caisses électroniques par utilisateur : dans sa fiche (Administration › Utilisateurs), cochez ses caisses électroniques. Chaque paiement MTN, Orange Money ou carte va à celle qui reçoit ce moyen, réglé dans Administration › Caisses (« Moyens reçus »).": "Several electronic registers per user: in their record (Administration › Users), tick their electronic registers. Each MTN, Orange Money or card payment goes to the one that receives that method, set in Administration › Registers (« Methods received »).",
  "Fenêtres : elles tiennent maintenant en entier sur les petits écrans et les PC portables réglés à 125 % ; les grandes fenêtres ne passent plus sous la barre verte de gauche et défilent quand elles sont plus hautes que l’écran.": "Windows: they now fit entirely on small screens and on laptops set to 125 %; large windows no longer slide under the green bar on the left and scroll when they are taller than the screen.",
  "Anglais : tous les écrans sont traduits, y compris l’administration, la comptabilité, les achats, le stock et le personnel.": "English: every screen is translated, including administration, accounting, purchases, stock and staff.",
  "Qui est là (présences du jour)": "Who is here (today's attendance)",
  "Borne de pointage": "Time clock kiosk",
  "Équipes, rotations et entrées": "Teams, rotations and entrances",
  "Sociétés prestataires (gardiennage, nettoyage)": "Contractor companies (security, cleaning)",
  "Pointer à la connexion au logiciel": "Clock in when logging into the software",
  "L’arrivée est notée à la première connexion du jour, le départ à la clôture de caisse ou par « Je pars ».": "Arrival is recorded at the first login of the day, departure at register closing or with « I'm leaving ».",
  "Borne de pointage à l’entrée": "Time clock kiosk at the entrance",
  "Un PC ou une tablette près de la porte : chacun y pointe en arrivant et en partant, même sans compte. Ce PC devient borne dans Personnel › Équipes et entrées.": "A PC or tablet near the door: everyone clocks in and out there, even without an account. This PC becomes a kiosk in Staff › Teams and entrances.",
  "… avec un badge": "… with a badge",
  "… avec un numéro et un code personnel": "… with a number and a personal code",
  "Pavé de chiffres à l’écran : pour un badge oublié, ou sans lecteur.": "On-screen keypad: for a forgotten badge, or without a reader.",
  "… avec une photo prise par la caméra": "… with a photo taken by the camera",
  "Une photo à chaque passage, visible dans le détail du jour : personne ne pointe à la place d’un autre.": "A photo at each scan, visible in the day's details: nobody clocks in for someone else.",
  "Deux passages rapprochés comptent pour un": "Two scans close together count as one",
  "Évite un départ noté par un double passage du badge.": "Avoids a departure recorded by a double badge scan.",
  "Plusieurs entrées, chacune avec sa borne": "Several entrances, each with its kiosk",
  "Sinon, une seule entrée.": "Otherwise, a single entrance.",
  "Personnel de sociétés prestataires": "Staff from contractor companies",
  "Vigiles ou agents d’entretien d’une société de gardiennage ou de nettoyage : ils pointent, leur société les paie. Sinon, tout le personnel est salarié du magasin.": "Guards or cleaners from a security or cleaning company: they clock in, their company pays them. Otherwise, all staff are employed by the store.",
  "Équipes et rotations": "Teams and rotations",
  "Matin, soir, nuit (une garde de nuit finit le lendemain), avec rotation d’une semaine à l’autre. Sinon, la semaine type de chacun (Planning).": "Morning, evening, night (a night shift ends the next day), rotating from one week to the next. Otherwise, each person's usual week (Schedule).",
  "Jours fériés légaux du Cameroun": "Cameroon public holidays",
  "Jour de l’an, Fête de la jeunesse, Vendredi saint, Fête du travail, Fête nationale, Ascension, Assomption, Noël : ni absence ni retard.": "New Year's Day, Youth Day, Good Friday, Labour Day, National Day, Ascension, Assumption, Christmas: neither absence nor lateness.",
  "Autres jours fériés": "Other public holidays",
  "Un par ligne : « AAAA-MM-JJ Libellé » (Aïd el-Fitr, Tabaski, qui suivent la lune), ou « MM-JJ Libellé » pour un jour fixe chaque année.": "One per line: « YYYY-MM-DD Label » (Eid al-Fitr, Tabaski, which follow the moon), or « MM-DD Label » for a fixed day every year.",
