  "Nouvelle équipe…": "New team…",
  "Une équipe a son horaire et ses jours. Une fin avant le début est une garde de nuit : elle finit le lendemain et compte pour le jour où elle commence. Chaque collaborateur reçoit une équipe fixe ou une rotation (Collaborateurs › Badge et pointage).": "A team has its hours and its days. An end before the start is a night shift: it ends the next day and counts for the day it starts. Each staff member gets a fixed team or a rotation (Staff › Badge and time clock).",
  "Tolérance": "Tolerance",
  "(le lendemain)": "(the next day)",
  "Aucune équipe. Créez par exemple Matin (06:00 → 14:00), Soir (14:00 → 22:00) et Nuit (22:00 → 06:00).": "No team. Create for example Morning (06:00 → 14:00), Evening (14:00 → 22:00) and Night (22:00 → 06:00).",
