  "Nouveau nom de «": "New name for «",
  "Renommer": "Rename",
  "L’entrée principale est créée au premier passage à la borne.": "The main entrance is created at the first kiosk scan.",
  "Ce PC": "This PC",
  "Un PC réglé en borne affiche la borne de pointage à la place de l’écran de connexion : le personnel y passe son badge en arrivant et en partant. « Connexion au logiciel » reste en bas de la borne pour le gérant.": "A PC set as a kiosk shows the time clock instead of the login screen: staff scan their badge there when arriving and leaving. « Log into the software » stays at the bottom of the kiosk for the manager.",
  "Ce PC est la borne de pointage de": "This PC is the time clock kiosk of",
