  "Les vigiles ou agents d’entretien fournis par une société ont leur fiche (catégorie « Agent d’une société prestataire ») et leur badge. Ils pointent comme les autres, sans salaire ni sous-compte : c’est leur société qui les paie. Le pointage du mois filtré par société sert à vérifier sa facture.": "Guards or cleaners provided by a company have their record (category « Contractor company agent ») and their badge. They clock in like the others, without salary or sub-account: their company pays them. The monthly time sheet filtered by company is used to check its invoice.",
