  "Badge et pointage": "Badge and time clock",
  "Aucun collaborateur. Ajoutez tout votre personnel, même ceux qui n’utilisent pas le logiciel (nettoyage, vigiles) : chacun a sa fiche, son badge et son pointage.": "No staff member. Add all your staff, even those who do not use the software (cleaning, guards): each one has a record, a badge and a time sheet.",
  "Agent ajouté : donnez-lui un badge (Badge et pointage)": "Agent added: give them a badge (Badge and time clock)",
