  "Choisissez un PC toujours allumé (la borne ou le PC du gérant), branché au même réseau que la pointeuse.": "Choose a PC that is always on (the kiosk or the manager's PC), on the same network as the time clock.",
  "Ce PC reçoit les pointeuses": "This PC receives the time clocks",
