  "Dans la pointeuse : Menu › Clé USB › Télécharger › Pointages (fichier « attlog »).": "In the time clock: Menu › USB stick › Download › Attendance (« attlog » file).",
  "déjà noté(s)": "already recorded",
  "Numéros sans collaborateur :": "Numbers without a staff member:",
