  "Aucune pointeuse encore : elle apparaît ici à son premier envoi par le réseau.": "No time clock yet: it appears here at its first upload over the network.",
  "Avertissement oral, écrit, blâme ou mise à pied : gardé au dossier, avec la lettre à faire signer.": "Oral or written warning, reprimand or suspension: kept in the file, with the letter to sign.",
