  "Aucun bon. Un bon d'achat se vend à la caisse (bouton « Bon d'achat »), un bon d'avoir se donne lors d'un retour remboursé en « Bon d'achat ».": "No voucher. A gift voucher is sold at the register (« Gift voucher » button), a credit voucher is given for a return refunded as « Gift voucher ».",
