  "Payé avec le bon": "Paid with the voucher",
  "Programmé : les prix changent seuls ce jour-là, les étiquettes sont prêtes la veille": "Scheduled: prices change by themselves that day, labels are ready the day before",
  "À une date": "On a date",
  "Bons d’achat : vendus à la caisse ou offerts, imprimés avec un code-barres et payés par ce code au moment de l’achat ; un remboursement peut aussi se faire en bon. Ventes › Bons d’achat suit ce qui reste sur chacun.": "Gift vouchers: sold at the register or given, printed with a barcode and paid with this code at purchase; a refund can also be made as a voucher. Sales › Gift vouchers tracks what is left on each one.",
  "Rappel de lot : un lot retiré par le fournisseur ou les autorités est bloqué à la vente ; le logiciel montre où il reste du stock, qui l’a acheté (avec le message à envoyer) et prépare le retour au fournisseur.": "Lot recall: a lot withdrawn by the supplier or the authorities is blocked from sale; the software shows where stock is left, who bought it (with the message to send) and prepares the return to the supplier.",
  "Transferts entre magasins : avant d’acheter, le logiciel propose de demander le produit à un autre magasin qui en a trop ; la demande s’expédie, se reçoit et garde les lots.": "Transfers between stores: before buying, the software offers to request the product from another store that has too much; the request is shipped, received and keeps the lots.",
  "Caisse retirée à": "Register removed from",
  ": attribuez-leur une caisse du bon type": ": assign them a register of the right type",
  "Le type se change tant que la caisse n'a pas servi (aucune journée, vente ni mouvement).": "The type can be changed as long as the register has not been used (no day, sale or movement).",
  "La caisse sera retirée aux utilisateurs qui la tiennent : attribuez-leur ensuite une caisse du bon type.": "The register will be removed from the users holding it: then assign them a register of the right type.",
  "Supprimer définitivement la caisse «": "Permanently delete the register «",
  "Caisse supprimée, retirée à": "Register deleted, removed from",
  "Supprimer la caisse": "Delete the register",
  "Remise à zéro des données d’essai": "Reset of the test data",
  "Après l’installation et la formation, effacez les ventes, achats, journées de caisse, dépenses, inventaires et mouvements de stock faits pour s’entraîner. Les réglages, les utilisateurs et leurs droits, les caisses, les dépôts, les produits (prix, codes-barres, conditionnements, rayons), les clients, les fournisseurs, le personnel et le plan comptable sont gardés.": "After installation and training, erase the sales, purchases, cash days, expenses, inventories and stock movements made for practice. Settings, users and their rights, registers, warehouses, products (prices, barcodes, packagings, departments), customers, suppliers, staff and the chart of accounts are kept.",
  "Ce PC est relié au serveur central : faites la remise à zéro avant de relier les PC.": "This PC is linked to the central server: reset before linking the PCs.",
