/** Textes avec un nombre, un numéro ou un nom : le premier motif qui correspond s'applique. */
export const EN_PATTERNS: [RegExp, string | ((m: RegExpExecArray, t: (fr: string) => string) => string)][] = [
  [/^Il manque (.+) : recomptez avant de clôturer\.$/, 'Short by $1: recount before closing.'],
  [/^Il y a en trop (.+) : recomptez avant de clôturer\.$/, 'Over by $1: recount before closing.'],
  [/^Annuler \((\d+) s\)$/, 'Undo ($1 s)'],
  [/^Fiche vidée \(1 article\)$/, 'Ticket cleared (1 item)'],
  [/^Fiche vidée \((\d+) articles\)$/, 'Ticket cleared ($1 items)'],
  [/^Ticket (\S+)$/, 'Receipt $1'],
  [/^Facture (\S+) enregistrée$/, 'Invoice $1 saved'],
  [/^Mise à jour (.+) prête$/, 'Update $1 ready'],
  [/^1 fiche à rapporter$/, '1 record to bring back'],
  [/^(\d+) fiches à rapporter$/, '$1 records to bring back'],
  [/^1 écart à justifier$/, '1 difference to justify'],
  [/^(\d+) écarts à justifier$/, '$1 differences to justify'],
  [/^1 charge en retard$/, '1 overdue expense'],
  [/^(\d+) charges en retard$/, '$1 overdue expenses'],
  [/^Version d'essai \((\d+) j\)$/, 'Trial version ($1 d)'],
  [/^Version d'essai$/, 'Trial version'],
  [/^Licence à renouveler \((\d+) j\)$/, 'Licence to renew ($1 d)'],
  [/^Licence à renouveler$/, 'Licence to renew'],
  [/^Licence expirée : ventes arrêtées dans (\d+) j$/, 'Licence expired: sales stop in $1 d'],
  [/^Version d'essai : il reste (\d+) jours?\. Activez votre licence dans Administration › Licence\.$/, 'Trial version: $1 day(s) left. Activate your licence in Administration › Licence.'],
  [/^La période d'essai est terminée : la caisse ne vend plus\. Activez votre licence dans Administration › Licence\.$/, 'The trial period is over: the register no longer sells. Activate your licence in Administration › Licence.'],
  [/^Licence à vie au nom de (.+)\.$/, 'Lifetime licence in the name of $1.'],
  [/^Synchronisé : (\d+) envoyée\(s\), (\d+) reçue\(s\)$/, 'Synced: $1 sent, $2 received'],
  [/^(.+) n'est pas ouverte$/, '$1 is not open'],
  [/^(.+) est fermée : ouvrez-la dans Trésorerie › Opérations de trésorerie$/, '$1 is closed: open it in Treasury › Treasury operations'],
  [/^Stock insuffisant pour (.+?) : (.+?)(?:\. Proposez à la place : (.+))?$/, (m) => `Insufficient stock for ${m[1]}: ${m[2]!.replace(/^il reste /, 'only ').replace(/^épuisé$/, 'sold out').replace(/ pièce$/, ' pcs')}${m[3] ? `. Offer instead: ${m[3]}` : ''}`],
  [/^Stock réservé pour (.+?) : ([\d,]+) mis de côté pour des commandes clients, (?:il en reste ([\d,]+) de libre|rien de libre)$/, (m) => `Stock reserved for ${m[1]}: ${m[2]} set aside for customer orders, ${m[3] ? `${m[3]} still free` : 'none free'}`],
  [/^Article inactif : (.+)$/, 'Inactive item: $1'],
  [/^Prix invalide : (.+)$/, 'Invalid price: $1'],
  [/^Remise supérieure au prix : (.+)$/, 'Discount higher than the price: $1'],
  [/^Référence de transaction obligatoire pour (.+)$/, 'Transaction reference required for $1'],
  [/^Le montant dépasse ce que doit le client \((.+)\)$/, 'The amount is more than the customer owes ($1)'],
  [/^Au-delà de (.+), le nom du client est obligatoire$/, 'Above $1, the customer name is required'],
  [/^(.+) a (.+) de factures échues non payées : accord du gérant nécessaire$/, '$1 has $2 of overdue unpaid invoices: manager approval required'],
  [/^La caisse centrale n'a que (.+) FCFA$/, 'The central cash only has $1 FCFA'],
  [/^Le client (.+) est désactivé$/, 'Customer $1 is deactivated'],
  [/^La commande (\S+) est annulée$/, 'Order $1 is cancelled'],
  [/^Commande (\S+) (enregistrée|préparée|annulée|chargée)$/, (m) => `Order ${m[1]} ${{ enregistrée: 'saved', préparée: 'prepared', annulée: 'cancelled', chargée: 'loaded' }[m[2]!]}`],
  [/^Facture récapitulative (\S+) créée$/, 'Summary invoice $1 created'],
  [/^Facture récapitulative (\S+)$/, 'Summary invoice $1'],
  [/^Annuler la facture récapitulative (\S+) \? Ses ventes pourront être reprises sur une autre\.$/, 'Cancel the summary invoice $1? Its sales can be put on another one.'],
  [/^Commander au fournisseur pour (\S+)$/, 'Order from the supplier for $1'],
  [/^Bon de commande (.+)$/, 'Purchase order $1'],
  [/^(\S+) · commandé$/, '$1 · ordered'],
  [/^(\S+) · reçu (.+)$/, '$1 · received $2'],
  [/^(\d+) articles?$/, (m) => `${m[1]} item${m[1] === '1' ? '' : 's'}`],
  [/^([^()]+) \((\d+)\)$/, (m, t) => `${t(m[1]!)} (${m[2]})`],
  [/^Montant (.+)$/, (m, t) => `${t(m[1]!)} amount`],
  [/^Consigne encaissée : (.+)$/, 'Deposit collected: $1'],
  [/^Consigne rendue : (.+)$/, 'Deposit refunded: $1'],
];
